INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('No jargon guidebook to doing community research published', 'no-jargon-guidebook-to-doing-community-research-published', '<p>A new guidebook called ‘Doing Community Research’ by Dr. Maura Adshead was published in May and it cuts through jargon to provide straightforward advice for community practitioners and academic researchers who want to work together.</p>

<p>Created in partnership with The Wheel and published by Boru Press, the book offers “a clear path toward meaningful, collaborative research”.</p>

<p>“It cuts through jargon to provide straightforward advice on how to build strong, effective partnerships,” say Boru Press. “Whether you are new to community-oriented research or looking to deepen your practice, this book offers a step-by-step roadmap -from planning and implementation to navigating the real-world challenges,” they say.</p>

<p>It helps both academic and community partners to better understand each other and it contains practical insights, real-world guidance, and links to open-access resources.</p>

<p>“With a focus on the Irish context, it underscores the growing importance of evidence-based approaches in the community and voluntary sector. Engaging, informative, and refreshingly clear, this is an essential resource for anyone committed to working together to create research that truly makes a difference,” say Boru Press.</p>

<figure><img decoding="async" width="1024" height="683" src="https://changingireland.ie/wp-content/uploads/2026/07/The-Wheel-0647-1024x683.jpg" alt="" srcset="https://changingireland.ie/wp-content/uploads/2026/07/The-Wheel-0647-1024x683.jpg 1024w, https://changingireland.ie/wp-content/uploads/2026/07/The-Wheel-0647-300x200.jpg 300w, https://changingireland.ie/wp-content/uploads/2026/07/The-Wheel-0647-768x512.jpg 768w, https://changingireland.ie/wp-content/uploads/2026/07/The-Wheel-0647-1536x1024.jpg 1536w, https://changingireland.ie/wp-content/uploads/2026/07/The-Wheel-0647-2048x1365.jpg 2048w, https://changingireland.ie/wp-content/uploads/2026/07/The-Wheel-0647-630x420.jpg 630w, https://changingireland.ie/wp-content/uploads/2026/07/The-Wheel-0647-150x100.jpg 150w, https://changingireland.ie/wp-content/uploads/2026/07/The-Wheel-0647-696x464.jpg 696w, https://changingireland.ie/wp-content/uploads/2026/07/The-Wheel-0647-1068x712.jpg 1068w, https://changingireland.ie/wp-content/uploads/2026/07/The-Wheel-0647-1920x1280.jpg 1920w" sizes="(max-width: 1024px) 100vw, 1024px" /></figure>

<h2>Who is Maura Adshead?</h2>

<p>Dr. Adshead is the Professor of Politics and Public Administration and Head of Community Engagement at the University of Limerick. She works with community groups, is an established author and has frequently carried out research for government bodies.</p>

<p>‘Doing Community Research’ is for sale for €24.99 &#8211; with all profits going towards funding a community research programme in UL. You can order ‘Doing Community Research’ from Boru Press: <a href="https://www.borupress.ie/bookshop/doing-community-research">borupress.ie</a></p>', 'A new guidebook called ‘Doing Community Research’ by Dr. Maura Adshead was published in May and it cuts through jargon to provide straightforward advice for community practitioners and academic researchers who want to work together. Created in partnership with The Wheel and published by Boru Press, the book offers “a clear path toward meaningful, collaborative', 'https://changingireland.ie/wp-content/uploads/2026/07/Author-Dr-Maura-Adshead-with-her-new-book-and-Emma-Murtagh-from-The-Wheel-which-supported-the-publication-of-Doing-Community-Research.jpg', '', '[{"slug":"opinion-advice","title":"OPINION/ADVICE"}]', '[{"slug":"maura-adshead","title":"Maura Adshead"},{"slug":"the-wheel","title":"The Wheel"},{"slug":"university-of-limerick","title":"University of Limerick"}]', '', 259355, 1, '2026-07-11T18:42:30Z', '2026-07-11T18:54:22Z', '2026-07-11T18:42:30Z')
