INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('10 reasons to join your local Public Participation Network!', '10-reasons-to-join-your-local-public-participation-network', '<p>Public Participation Networks (PPNs) were established by the government in 2014 to encourage community groups to input into policy and decision-making. They are a way for community groups to ensure that decisions made by local authorities reflect their experiences and expertise.<br>We were encouraged by Mary McKeon, co-ordinator of Leitrim PPN, to remind our readers of the benefits of joining. Our thanks to Mary and here goes with her list of benefits for groups and citizens in those groups:<br>1 Grow and develop through free training supports.<br>2 Influence policy making decisions relevant to your county.<br>3 Feed into consultations and make submissions at local, regional and national level.<br>4 Valuable local and regional networking opportunities.<br>5 Access to community news and information. e.g. PPN e-bulletins.<br>6 Advertise your group&#8217;s activities via your PPN.<br>7 Learn of training and funding opportunities, consultations and submissions.<br>8 Become part of a linkage group which is a group of member stakeholder organisations with a common interest.<br>9 Through linkage groups have your views heard and contribute to local policy.<br>10 Nominate members to sit on boards and committees.</p>

<p>PPNs were set up to:</p>

<ul>
<li>Be the main way for local authorities to consult the public on plans, strategies, policies, consultations, surveys and submissions.</li>

<li>Facilitate the representation and participation of the public on local authority committees. e.g. Local Community and Development Committees.</li>

<li>To provide networking opportunities and act as a hub around which information is shared.</li>
</ul>

<p>Find the Public Participation Network for your county here: <a href="https://bit.ly/Find-Your-PPN-Here">https://bit.ly/Find-Your-PPN-Here</a></p>', 'Mary McKeon, Public Participation Network (PPN) co-ordinator in Co. Leitrim, reminds us of the benefits of joining your local network.', 'https://changingireland.ie/wp-content/uploads/2026/06/PPN-Leitrim-Grant-Writing-workshop-held-May-6-2026-PPN-Leitrim-on-FB.jpg', '', '[{"slug":"policy-strategy","title":"Policy & Strategy"}]', '[{"slug":"department-of-rural-and-community-development-and-the-gaeltacht","title":"Department of Rural and Community Development and the Gaeltacht"},{"slug":"leitrim","title":"Leitrim"},{"slug":"public-participation-network","title":"Public Participation Network"}]', '', 259230, 1, '2026-07-11T18:05:55Z', '2026-07-11T18:05:57Z', '2026-07-11T18:05:55Z')
