INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('€4m investment in rural social enterprise through new PEACEPLUS project', 'e4m-investment-in-rural-social-enterprise-through-new-peaceplus-project', '<p>RiSE is supported by PEACEPLUS, a programme managed by the Special EU Programmes Body (SEUPB). It aims to strengthen rural communities by providing training, networking opportunities, and practical support to help organisations enhance sustainability, expand income generation, and increase access to vital community services.</p>
<p>SEUPB chief executive Gina McIntyre said, “By investing in developing approaches to social enterprise and innovation, we are helping communities work together across borders and traditions, creating opportunities that build trust and future economic opportunities. Projects like RiSE are vital to peacebuilding because they turn shared challenges into shared solutions, with cooperation and inclusion at the heart of community life.”</p>
<p>She noted that, “Significant developments have been made in the provision of collaborative cross-border services in recent years, providing equality of opportunity for citizens in rural areas.”</p>
<p>Through networking, events, and activities, RiSE will encourage and facilitate collaboration between rural communities on a cross-border and cross-community basis. Participating groups and organisations will benefit from shared learning and tailored training designed to maximise income generation, strengthen long term sustainability, and widen access to essential community services. A dedicated element of the project will also focus on inspiring the next generation of social entrepreneurs through a programme of youth-focused training and collaboration.</p>
<h3>Ministers welcome RiSE project</h3>
<p>The Minister for Rural and Community Development and the Gaeltacht, Dara Calleary, and Minister of State with Responsibility for Community Development and Charities, Jerry Buttimer, welcomed the announcement.<br />
Minister Calleary congratulated everyone involved in creating the RiSE project.</p>
<p>“I am happy that my Department of Rural and Community Development and the Gaeltacht (DRCDG), working with the Special EU Programmes Body and the Department of Agriculture, Environment and Rural Affairs in Northern Ireland, will continue to provide assistance for this remarkable project. This project will bring lasting advantages to the area”.</p>
<p>Minister Buttimer said, “This important financing will enhance the availability of communal areas and services in rural locations. Planned investment will empower communities to flourish and achieve their complete economic, social, and environmental capabilities”.</p>
<p>Minister of Agriculture, Environment and Rural Affairs, Andrew Muir, said: “I am delighted that my Department, along with DRCDG and SEUPB, is providing funding to the RiSE project, which will strengthen rural social enterprise and build on a connected, collaborative cross border community.”</p>
<p>He said the project will “support new social enterprise initiatives and provide opportunities for young people to design and lead meaningful social action.”</p>
<h3>Includes young people aged 14-25</h3>
<p>The project brings together a multi-stakeholder partnership comprising of Rural Action which will lead the project along with Irish Rural Link, Scotland Social Enterprise Academy and Social Enterprise NI (SENI) &#8211; with Community Finance Ireland as an associate partner. Rural Action was formed in 2019 as a regional delivery organisation with a focus on supporting grassroots communities.<br />
Speaking at the launch, Rural Action&#8217;s chief executive Teresa Canavan said the RiSE programme brings together three strands: Social Enterprise Leadership and Development, Making it Happen (which focuses on turning ideas into action and offering practical support and guidance), and Youth Social Enterprise, aimed at supporting people aged 14–25.</p>
<h3>More information</h3>
<p>Further information is available at <a href="http://ruralaction.co">ruralaction.co</a> as well as on the websites of all programme partners.</p>', 'An investment of €3,971,440 in rural renewal was announced in February at the launch of the Rural Innovation and Social Enterprise (RiSE) Project, an initiative designed to put social enterprise at the centre of sustainable rural development.', 'https://changingireland.ie/wp-content/uploads/2026/04/Group-photo-at-RiSE-launch-E4m-investment-in-rural-social-enterprise-through-PEACEPLUS-e1775086154284.jpg', '', '[{"slug":"uncategorized","title":"Uncategorized"}]', '[{"slug":"peaceplus","title":"PEACEPLUS"},{"slug":"social-enterprise","title":"social enterprise"}]', '', 257733, 1, '2026-04-01T23:26:02Z', '2026-07-01T17:35:45Z', '2026-04-01T23:26:02Z')
