INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Kerry Social Farming going strong, seeks more farmers', 'kerry-social-farming-going-strong-seeks-more-farmers', '<p>Over 70 participants and 40 farms are now active in Kerry Social Farming (KSF) with five new host farmers joining last year.</p>
<p>Éamon Horgan, a host farmer from Kilgarvan, speaking at the organisation&#8217;s AGM, said that there are many people in Kerry waiting for a chance to go social farming and he urged other farmers to come forward and volunteer.</p>
<p>Since 2013, Kerry Social Farming has operated a voluntary model of social farming. It provides meaningful weekly working farm visits for people with disabilities and those accessing mental health services and the impact on participants has long been recognised as beneficial.</p>
<p>Over 90 people attended the AGM, held in Killarney, showing the interest in the county in social farming. The attendees included host farmers, participants and their families, service provider agencies, project partners and representatives of social farming projects.</p>
<p>At the AGM, social farming participants Pat O’Connor, Tracy McCarthy, Antoinette O’Sullivan, Seamus McCarthy and Tim Heffernan shared their social farming stories.</p>
<p>Other speakers included Marie Carr (outreach manager, Kerry Parents and Friends Association), Brenda McNamara (a manager of day services with St John of God) and Patrice O’Neill (HSE day service opportunities co-ordinator).</p>
<p>Peter Johnston, assistant principal officer with the Department of Agriculture, Food and Marine also attended, as did Noel Spillane, CEO of South Kerry Development Partnership. Their respective organisations are supportive of KSF’s voluntary and collaborative work.</p>
<p>Last year, almost 2,500 days of social farming were held in Kerry.</p>
<p>For more information visit: <a href="http://www.kerrysocialfarming.ie">www.kerrysocialfarming.ie</a></p>', 'Over 70 participants and 40 farms are now active in Kerry Social Farming (KSF) with five new host farmers joining last year. Éamon Horgan, a host farmer from Kilgarvan, speaking at the organisation’s AGM, said that there are many people in Kerry waiting for a chance to go social farming and he urged other farmers', 'https://changingireland.ie/wp-content/uploads/2026/04/Kerry-Social-Farming-AGM8-scaled-1.jpg', '', '[{"slug":"activism-volunteering","title":"Activism & Volunteering"}]', '[{"slug":"social-farming","title":"social farming"}]', '', 257730, 1, '2026-04-01T23:10:06Z', '2026-07-01T17:31:27Z', '2026-04-01T23:10:06Z')
