INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Ireland now has 25 “Libraries of Sanctuary”', 'ireland-now-has-25-libraries-of-sanctuary', '<p>Many libraries have included offering solidarity with refugees in their action plans. Portlaoise Library was the first to become a library of sanctuary, followed by:</p>
<ul>
<li>Louth County Libraries (5 libraries)</li>
<li>Westmeath County Libraries (5 libraries)</li>
<li>Wicklow Libraries (13 libraries)</li>
<li>Plus libraries in Offaly and Fingal.</li>
</ul>
<p><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2026/04/Library-of-Sanctuary-1.png" alt="" width="745" height="443" /></p>
<p>An organisation called <a href="https://www.posi.ie/">Places of Sanctuary Ireland</a> provides support. Pointing to examples from around the country it says that many libraries “have responded proactively and creatively to the arrival of refugees and migrants.”</p>
<p>As a library user in Dundalk, a teacher who came from Zimbabwe, said:</p>
<blockquote><p>“When I moved to Dundalk with my children, the library soon become our safe haven. We received a hearty welcome and felt such a sense of belonging, it was a wonderful way to start integrating in Dundalk.”</p></blockquote>
<p>The east coast has seen major population growth. For example, the population of Drogheda and Dundalk combined is 139,000 people with 19% of its residents born outside Ireland.</p>
<p>For more information on Places of Sanctuary, including libraries, visit: <a href="http://posi.ie">posi.ie</a></p>', 'At least 25 of the state’s 330 public libraries have taken agreed steps to welcome refugees and people seeking asylum and all newcomers to an area. Known as Libraries of Sanctuary they have committed to creating a culture of welcome and inclusion.', 'https://changingireland.ie/wp-content/uploads/2026/04/Libraries-of-Sanctuary-composite.png', '', '[{"slug":"refugees-ukraine","title":"Refugees/Ukraine"}]', '[{"slug":"libraries-ireland","title":"libraries ireland"}]', '', 257731, 1, '2026-04-01T23:05:35Z', '2026-06-25T11:58:02Z', '2026-04-01T23:05:35Z')
