INSERT INTO posts (title, slug, content, excerpt, image_url, image_alt, categories, tags, author, wp_id, published, created_at, updated_at, published_at)
VALUES ('Record-setting Limerick jockeys and equine students receive awards', 'record-setting-limerick-jockeys-and-equine-students-receive-awards', '<p>Jockeys <strong>Wesley Joyce and Terry Casey</strong> and showjumpers <strong>Aoife Leonard and Emma Downey</strong> were honoured by staff and supporters at a ceremony on Monday, March 23, for their achievements.</p>
<p>Wesley’s winning ways in the saddle are well known, Terry has three wins to his credit, while Aoife and Emma recently achieved their British Horse Society (BHS) Stage 2 certificates. They are among the youngest candidates ever to sit the BHS exams.</p>
<p><figure aria-describedby="caption-attachment-256214"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2026/04/Emma-Downey-and-Aoife-Leonard.jpg" alt="" width="2479" height="1906" /><figcaption><em>• Emma Downey and Aoife Leonard.</em></figcaption></figure></p>
<p>Aoife is 16 years old and lives in Cosgrove Park, Moyross, and Emma, also 16, lives in Meelick. Both received support on their journeys from MYA and Clonshire Equestrian Centre. Having earned the internationally recognised BHS qualification, they can now find employment in the industry and they are already working to progress onto the next BHS award level.</p>
<p><figure aria-describedby="caption-attachment-256215"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2026/04/Wesley-Joyce-and-family.jpg" alt="" width="2438" height="1928" /><figcaption><em>• Wesley Joyce and family.</em></figcaption></figure></p>
<p>Wesley is hugely admired nationally for his winning ways, his determination, and his courage in overcoming great adversity.</p>
<p>Terry Casey from Southill has three race wins to his name. He won a Limerick Divisional Garda Youth Award in 2025 and went on to receive the National Award just before Christmas &#8211; which was officially presented to him at the ceremony in MYA by Chief Supt. Derek Smart.</p>
<p><figure aria-describedby="caption-attachment-256216"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2026/04/Chief-Supt.-Derek-Smart-presents-Terry-Casey-with-his-trophy.jpg" alt="" width="1899" height="1905" /><figcaption><em>• Terry Casey is presented with his trophy by Chief Superintendent Derek Smart.</em></figcaption></figure></p>
<p>Both Terry and Wesley received support from MYA in their youth and Aoife and Emma continue to receive support and encouragement. All the awardees were accompanied by family members for the special occasion.</p>
<p><figure aria-describedby="caption-attachment-256213"><img loading="lazy" decoding="async" src="https://changingireland.ie/wp-content/uploads/2026/04/IMG_8143.jpg" alt="" width="2384" height="1622" /><figcaption><em>• Donal Fitzgibbon, chairperson of MYA’s Equine Committee.</em></figcaption></figure></p>
<p>Donal Fitzgibbon, chairperson of MYA’s Equine Committee, paid tribute to the young people and staff involved in the Academy’s Equine Programme.</p>
<p>Addressing Aoife and Emma, he said, “Our hope is that they continue to progress to instructor level and come back and work for us in the roll-out of the programme.”</p>
<p>He congratulated Terry on his wins and awards saying that he “continues to inspire young people across the city.”</p>
<p>Speaking of Wesley he said, “To be in contention for the National Apprentice Award two years running is a significant achievement for any person. To succeed at such a high level is an inspiration for all our young people on the equine programme.</p>
<p>“The programme has gone from one primary school in 2007 to now having fourteen schools across the city involved. There are approximately 100 young people involved with the current programme, both in school and out at the stables in Clare Equestrian Centre and Clonshire Equestrian Centre,” he said.</p>
<p>He also paid tribute to funders including the Department of Agriculture, Food and the Marine, Limerick City and County Council Regeneration Programme and Moyross Youth Diversion Project.</p>
<blockquote><p><a href="https://changingireland.ie/i-want-to-be-a-jockey-like-wesley/">“I want to be a jockey like Wesley”</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="““I want to be a jockey like Wesley”” — Changing Ireland" src="https://changingireland.ie/i-want-to-be-a-jockey-like-wesley/embed/#?secret=LoZ3iJ4jpV#?secret=P7ccfT2S2N" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<blockquote><p><a href="https://changingireland.ie/ace-jockey-cathy-gannon-has-advice-for-aspiring-jockeys-from-limerick/">Ace jockey Cathy Gannon has advice for aspiring jockeys from Limerick</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Ace jockey Cathy Gannon has advice for aspiring jockeys from Limerick” — Changing Ireland" src="https://changingireland.ie/ace-jockey-cathy-gannon-has-advice-for-aspiring-jockeys-from-limerick/embed/#?secret=uQ1VwSnjXD#?secret=wzrNruebBG" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<blockquote><p><a href="https://changingireland.ie/moyross-youth-academy-participants/">3 people who had life-changing experiences with Moyross Youth Academy</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“3 people who had life-changing experiences with Moyross Youth Academy” — Changing Ireland" src="https://changingireland.ie/moyross-youth-academy-participants/embed/#?secret=MNWNfAqfS3#?secret=qrhDUneVPy" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>
<blockquote><p><a href="https://changingireland.ie/moyross-youth-academy-launch/">Is new Youth Academy proof Moyross has turned a corner?</a></p></blockquote>
<p><iframe sandbox="allow-scripts" security="restricted" title="“Is new Youth Academy proof Moyross has turned a corner?” — Changing Ireland" src="https://changingireland.ie/moyross-youth-academy-launch/embed/#?secret=88MZtL7Mob#?secret=HO8hhkpkKS" width="600" height="338" frameborder="0" marginwidth="0" marginheight="0" scrolling="no"></iframe></p>', 'Two professional jockeys and two teenage showjumpers who have set records in the equestrian world – all from Limerick – have received special awards from Moyross Youth Academy (MYA).', 'https://changingireland.ie/wp-content/uploads/2026/04/L-to-R-Jockeys-Wesley-Joyce-and-Terry-Casey-and-showjumpers-Emma-Downey-and-Aoife-Leonard-were-honoured-by-Moyross-Youth-Academy-scaled-1.jpg', '', '[{"slug":"education-training","title":"Education & Training"}]', '[{"slug":"moyross","title":"Moyross"}]', '', 257728, 1, '2026-04-01T19:22:27Z', '2026-07-01T19:15:06Z', '2026-04-01T19:22:27Z')
